func testAccVertexAIRagCorpus_vertexAiRagCorpusFullExample(context map[string]interface{}) string {
	return acctest.Nprintf(`
resource "google_vertex_ai_rag_corpus" "rag_corpus" {
  display_name = "%{display_name}"
  description  = "A full RAG corpus created by Terraform"
  region       = "us-west1"

  vector_db_config {
    rag_embedding_model_config {
      vertex_prediction_endpoint {
        endpoint = "projects/${data.google_project.project.project_id}/locations/us-west1/publishers/google/models/text-embedding-005"
      }
    }
    rag_managed_db {
      ann {
        tree_depth = 3
        leaf_count = 100
      }
    }
  }

  encryption_spec {
    kms_key_name = "%{kms_key_name}"
  }

  depends_on = [google_kms_crypto_key_iam_member.crypto_key]
}

resource "google_kms_crypto_key_iam_member" "crypto_key" {
  crypto_key_id = "%{kms_key_name}"
  role          = "roles/cloudkms.cryptoKeyEncrypterDecrypter"
  member        = "serviceAccount:service-${data.google_project.project.number}@gcp-sa-vertex-rag.iam.gserviceaccount.com"
}

data "google_project" "project" {}
`, context)
}

func testAccCheckVertexAIRagCorpusDestroyProducer(t *testing.T) func(s *terraform.State) error {
	return func(s *terraform.State) error {
		for name, rs := range s.RootModule().Resources {
			if rs.Type != "google_vertex_ai_rag_corpus" {
				continue
			}
			if strings.HasPrefix(name, "data.") {
				continue
			}

			config := acctest.GoogleProviderConfig(t)
			url, err := tpgresource.ReplaceVarsForTest(config, rs, fmt.Sprintf("%s%s", transport_tpg.BaseUrl(vertexai.Product, config), "projects/{{project}}/locations/{{region}}/ragCorpora/{{name}}"))
			if err != nil {
				return err
			}

			billingProject := ""

			if config.BillingProject != "" {
				billingProject = config.BillingProject
			}

			_, err = transport_tpg.SendRequest(transport_tpg.SendRequestOptions{
				Config:    config,
				Method:    "GET",
				Project:   billingProject,
				RawURL:    url,
				UserAgent: config.UserAgent,
			})
			if err == nil {
				return fmt.Errorf("VertexAIRagCorpus still exists at %s", url)
			}
		}

		return nil
	}
}
